CALL {
  MATCH (ch:CrowdHour) WHERE ch.camera_location CONTAINS 'keynote' AND ch.hour_utc >= '2025-12-08T00:00:00Z' AND ch.hour_utc < '2025-12-09T00:00:00Z'
  RETURN substring(ch.hour_utc, 0, 13) + ':00:00Z' AS hour, ch.avg_hc AS avg_head_count
}
WITH hour, avg_head_count
RETURN hour, avg_head_count ORDER BY hour
